import React, { useState, useEffect } from "react";
import axios from "../../utils/axiosConfig";
import {
  FaUser,
  FaPhone,
  FaEnvelope,
  FaIdCard,
  FaMotorcycle,
  FaMapMarkerAlt,
  FaStar,
  FaEdit,
  FaSave,
  FaTimes,
} from "react-icons/fa";
import "../../styles/UserProfile.css";

const apiBaseUrl = "/shipper";

const ShipperProfileContent = () => {
  const [profile, setProfile] = useState({});
  const [loading, setLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    fullName: "",
    phoneNumber: "",
    vehicleType: "",
    licensePlate: "",
  });

  const fetchProfileData = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${apiBaseUrl}/info`);
      const { user, shipperDetails } = response.data;

      setProfile({ user, shipperDetails });

      // Lấy phoneNumber từ shipperDetails thay vì user
      setFormData({
        fullName: user.fullName || "",
        phoneNumber: shipperDetails?.phoneNumber || "",
        vehicleType: shipperDetails?.vehicleType || "Motorbike",
        licensePlate: shipperDetails?.licensePlate || "",
      });
    } catch (err) {
      console.error("Lỗi tải hồ sơ:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProfileData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await axios.put(`${apiBaseUrl}/info`, {
        fullName: formData.fullName,
        phone: formData.phoneNumber, // Gửi field phone lên server
        vehicleType: formData.vehicleType,
        licensePlate: formData.licensePlate,
      });
      setIsEditing(false);
      fetchProfileData();
      alert("Cập nhật thông tin thành công!");
    } catch (err) {
      alert("Cập nhật thất bại.");
    } finally {
      setLoading(false);
    }
  };

  if (loading && !isEditing)
    return <div className="user-profile-content">Đang tải dữ liệu...</div>;

  const user = profile.user || {};
  const details = profile.shipperDetails || {};

  return (
    <div className="shipper-profile-view">
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          marginBottom: "20px",
        }}
      >
        <h2 style={{ color: "var(--primary-color)", margin: 0 }}>
          Hồ Sơ Shipper
        </h2>
        {!isEditing && (
          <button
            className="btn btn-primary"
            onClick={() => setIsEditing(true)}
          >
            <FaEdit /> Chỉnh sửa hồ sơ
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit}>
        <div className="profile-grid">
          {/* Ô THÔNG TIN CÁ NHÂN */}
          <div className="info-card">
            <h4
              className="input-label"
              style={{
                borderBottom: "1px solid #eee",
                paddingBottom: "10px",
                marginBottom: "20px",
                color: "var(--primary-color)",
              }}
            >
              <FaUser /> Thông tin định danh
            </h4>

            <div className="input-group">
              <label className="input-label">
                <FaIdCard /> Họ và Tên
              </label>
              <input
                name="fullName"
                className="profile-input"
                value={formData.fullName}
                onChange={(e) =>
                  setFormData({ ...formData, fullName: e.target.value })
                }
                disabled={!isEditing}
              />
            </div>

            <div className="input-group">
              <label className="input-label">
                <FaEnvelope /> Email hệ thống
              </label>
              <input
                className="profile-input"
                value={user.email || ""}
                disabled
              />
            </div>

            <div className="input-group">
              <label className="input-label">
                <FaPhone /> Số điện thoại liên lạc
              </label>
              <input
                name="phoneNumber"
                className="profile-input"
                placeholder="Nhập số điện thoại..."
                value={formData.phoneNumber}
                onChange={(e) =>
                  setFormData({ ...formData, phoneNumber: e.target.value })
                }
                disabled={!isEditing}
              />
            </div>
          </div>

          {/* Ô THÔNG TIN VẬN CHUYỂN */}
          <div className="info-card">
            <h4
              className="input-label"
              style={{
                borderBottom: "1px solid #eee",
                paddingBottom: "10px",
                marginBottom: "20px",
                color: "var(--primary-color)",
              }}
            >
              <FaMotorcycle /> Thông tin vận chuyển
            </h4>

            <div className="input-group">
              <label className="input-label">Loại phương tiện</label>
              <select
                className="profile-input"
                value={formData.vehicleType}
                onChange={(e) =>
                  setFormData({ ...formData, vehicleType: e.target.value })
                }
                disabled={!isEditing}
              >
                <option value="Motorbike">Xe máy</option>
                <option value="Car">Ô tô</option>
                <option value="Truck">Xe tải</option>
              </select>
            </div>

            <div className="input-group">
              <label className="input-label">Biển số xe</label>
              <input
                className="profile-input"
                value={formData.licensePlate}
                onChange={(e) =>
                  setFormData({ ...formData, licensePlate: e.target.value })
                }
                disabled={!isEditing}
              />
            </div>

            <div className="input-group">
              <label className="input-label">
                <FaMapMarkerAlt /> Khu vực đăng ký
              </label>
              <div
                className="profile-input"
                style={{ backgroundColor: "var(--bg-light)" }}
              >
                {details.workingArea?.join(", ") || "Toàn quốc"}
              </div>
            </div>
          </div>
        </div>

        {/* PHẦN HIỂN THỊ TRẠNG THÁI (Chỉ xem) */}
        {!isEditing && (
          <div
            className="info-card"
            style={{
              marginTop: "20px",
              display: "flex",
              justifyContent: "space-around",
            }}
          >
            <div style={{ textAlign: "center" }}>
              <p style={{ margin: 0, color: "#666", fontSize: "0.9em" }}>
                Trạng thái
              </p>
              <strong
                className={
                  details.status === "ACTIVE"
                    ? "status-completed"
                    : "status-pending"
                }
              >
                {details.status || "N/A"}
              </strong>
            </div>
            <div
              style={{
                textAlign: "center",
                borderLeft: "1px solid #eee",
                paddingLeft: "40px",
              }}
            >
              <p style={{ margin: 0, color: "#666", fontSize: "0.9em" }}>
                Điểm uy tín
              </p>
              <strong>
                {details.rating || 5}{" "}
                <FaStar style={{ color: "var(--warning-color)" }} />
              </strong>
            </div>
          </div>
        )}

        {isEditing && (
          <div
            style={{
              display: "flex",
              gap: "10px",
              justifyContent: "flex-end",
              marginTop: "25px",
            }}
          >
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setIsEditing(false)}
            >
              <FaTimes /> Hủy
            </button>
            <button type="submit" className="btn btn-success">
              <FaSave /> Lưu hồ sơ
            </button>
          </div>
        )}
      </form>
    </div>
  );
};

export default ShipperProfileContent;
